import os, requests

url = "https://api-platform.wesog.com/api/v1/storage/upload"
headers = {"X-API-Key": os.environ["WESOG_API_KEY"], "Idempotency-Key": "6f1c2a9e-0000-4000-8000-000000000001"}
data = {"relative_path": "events/2026/madrid/IMG_0412.jpg"}
files = {"file": open("IMG_0412.jpg", "rb")}
response = requests.post(url, headers=headers, data=data, files=files)
response.raise_for_status()
print(response.status_code, response.text[:500] if response.status_code == 204 else response.json())

const url = "https://api-platform.wesog.com/api/v1/storage/upload";
const headers = { "X-API-Key": process.env.WESOG_API_KEY, "Idempotency-Key": crypto.randomUUID() };
const form = new FormData();
form.append("file", new Blob([await (await import("node:fs/promises")).readFile("IMG_0412.jpg")]), "IMG_0412.jpg");
form.append("relative_path", "events/2026/madrid/IMG_0412.jpg");
const response = await fetch(url, { method: "POST", headers, body: form });
if (!response.ok) throw new Error(await response.text());
console.log(response.status, response.status === 204 ? "" : await response.json());

